  "ai.prompt": "# Summarize a document with DeepSeek using a system message and moderate temperature\n- group: ai\n  name: prompt\n  params:\n    provider: deepseek\n    apiKey: '{{ deepseekKey }}'\n    prompt: 'Summarize the following document: {{ documentText }}'\n    systemMessage: 'You are a concise technical writer. Return plain text only.'\n    temperature: 0.5\n    maxTokens: 300\n",
  "api.auth": "# Authenticate with Google OAuth2, reusing/refreshing the token stored in a global\n# variable (create \"googleGmailToken\" once via the Variables page before first use)\n- group: api\n  name: auth\n  params:\n    type: oauth2\n    clientId: '{{ _env.GOOGLE_CLIENT_ID }}'\n    clientSecret: '{{ _env.GOOGLE_CLIENT_SECRET }}'\n    scopes:\n      - 'https://www.googleapis.com/auth/gmail.readonly'\n      - 'https://www.googleapis.com/auth/calendar.readonly'\n    authEndpoint: 'https://accounts.google.com/o/oauth2/v2/auth'\n    tokenEndpoint: 'https://oauth2.googleapis.com/token'\n    token: '{= _global.googleGmailToken =}'\n  destination: _global.googleGmailToken\n",
  "api.basicAuth": "# Build a Basic Auth header value and persist it for reuse across every call to the site\n- group: api\n  name: basicAuth\n  params:\n    username: '{{ _env.DRUPAL_USER }}'\n    password: '{{ _env.DRUPAL_PASS }}'\n  destination: _global.drupalBasicAuth\n",
