  "api.request": "# Fetch the 5 most recent Gmail messages using an OAuth2 token\n- group: api\n  name: request\n  params:\n    url: 'https://gmail.googleapis.com/gmail/v1/users/me/messages'\n    method: GET\n    headers:\n      Authorization: 'Bearer {{ googleToken.access_token }}'\n    parameters:\n      maxResults: 5\n  destination: gmailMessages\n",
